import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../App.css";

const MySales = () => {
  const [sales, setSales] = useState([]);
  const [totalEarnings, setTotalEarnings] = useState(0);
  const [loading, setLoading] = useState(true);
  const userId = sessionStorage.getItem("userId");

  useEffect(() => {
    if (userId) {
      fetch(`${API_BASE_URL}/api/sales/user/${userId}`)
        .then((res) => res.json())
        .then((data) => {
          if (Array.isArray(data)) {
            setSales(data);
            const total = data.reduce((sum, item) => sum + parseFloat(item.price || 0), 0);
            setTotalEarnings(total);
          } else {
            console.error("Sales data is not an array:", data);
            setSales([]);
            setTotalEarnings(0);
          }
          setLoading(false);
        })
        .catch((err) => {
          console.error("Error loading sales:", err);
          setSales([]);
          setTotalEarnings(0);
          setLoading(false);
        });
    } else {
      setLoading(false);
    }
  }, [userId]);

  const toggleShipped = async (listingId) => {
    await fetch(`${API_BASE_URL}/api/listings/${listingId}/shipped`, { method: "PUT" });
    setSales((prev) =>
      prev.map((item) =>
        item.id === listingId ? { ...item, shipped: true } : item
      )
    );
  };

  const handleEarlyPayout = () => {
    const confirmPayout = window.confirm("Payout now for a 3% early payout charge?");
    if (confirmPayout) {
      const fee = totalEarnings * 0.03;
      const finalPayout = totalEarnings - fee;
      alert(
        `✅ Payout Successful!\nTotal: $${totalEarnings.toFixed(2)}\nEarly Fee (3%): -$${fee.toFixed(2)}\nFinal Payout: $${finalPayout.toFixed(2)}`
      );
      setTotalEarnings(0);
    }
  };

  return (
    <div className="dashboard-wrapper">
      <Navbar />
      <main className="my-sales-container">
        <div className="earnings-summary-card">
          <h2>Total Earnings</h2>
          <p className="earnings-amount">${totalEarnings.toFixed(2)}</p>
          <p className="pay-info">Weekly payout every Friday</p>
          {totalEarnings > 0 && (
            <button className="payout-now-btn" onClick={handleEarlyPayout}>
              💸 Payout Now
            </button>
          )}
        </div>

        <h2 className="section-heading">Items Sold</h2>

        {loading ? (
          <p>Loading sales...</p>
        ) : sales.length === 0 ? (
          <p>No sales yet.</p>
        ) : (
          <div className="sales-list">
            {sales.map((item) => (
              <div key={item.id} className="sales-item-card">
                <div className="sales-item-left">
                  <img src={item.image} alt={item.title} className="sales-item-img" />
                </div>
                <div className="sales-item-right">
                  <h3>{item.title}</h3>
                  <p><strong>Category:</strong> {item.category}</p>
                  <p><strong>Price:</strong> ${parseFloat(item.price).toFixed(2)}</p>
                  <p><strong>Ship To:</strong> 
                    {item.shipping_info?.address1}, {item.shipping_info?.city}, {item.shipping_info?.state} {item.shipping_info?.zip}, {item.shipping_info?.country}
                  </p>
                  <p><strong>Status:</strong> {item.shipped ? "✅ Shipped" : "❌ Not Shipped"}</p>
                  {!item.shipped && (
                    <button className="mark-shipped-btn" onClick={() => toggleShipped(item.id)}>
                      Mark as Shipped
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </main>
      <Footer />
    </div>
  );
};

export default MySales;
